const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
const values = input.slice(1, n + 1);
const height = Math.max(...values);

const output = [];

for (let row = 0; row < height; row++) {
  const threshold = height - row;
  output.push(values.map(value => value >= threshold ? '1' : '0').join(' '));
}

console.log(output.join('\n'));
